package dev.pedro.learning.ecommerce.notification;import dev.pedro.learning.ecommerce.notification.application.NotificationDeliveryService;import dev.pedro.learning.ecommerce.notification.provider.*;import io.quarkus.test.junit.QuarkusTest;import jakarta.inject.Inject;import org.junit.jupiter.api.Test;import java.util.UUID;import static org.junit.jupiter.api.Assertions.assertEquals;@QuarkusTest class NotificationRetryTest{@Inject FakeEmailProvider provider;@Inject NotificationDeliveryService delivery;@Test void retriesWithBackoffUntilProviderRecovers(){provider.reset();provider.failFirstN(2);provider.mode(EmailProviderMode.FAIL_FIRST_N_ATTEMPTS);UUID eventId=UUID.randomUUID();delivery.deliver(eventId,UUID.randomUUID(),"learner@example.com");assertEquals(3,delivery.attempts(eventId));assertEquals(3,provider.calls());assertEquals(1,provider.successes());delivery.clear(eventId);}}